<?php
namespace Modules\Inventory\Models;
use Illuminate\Database\Eloquent\Model;
class InventoryAsset extends Model { protected $table='inventory_assets'; protected $fillable=['material_id','category_id','classroom_id','asset_code','name','category','quantity','broken_quantity','unit','holding_unit_id','grade','manufacture_year','usage_year','install_address','status','purchase_date','expiry_date','broken_at','repair_started_at','repair_completed_at','repair_performer','note','description']; protected $casts=['quantity'=>'integer','broken_quantity'=>'integer','purchase_date'=>'date','expiry_date'=>'date','broken_at'=>'date','repair_started_at'=>'date','repair_completed_at'=>'date']; protected static function booted(){static::updating(function(self $asset){if(request()->routeIs('inventory.proposals.decide')&&$asset->isDirty('classroom_id')&&$asset->classroom_id===null&&(int)$asset->quantity>0)$asset->classroom_id=$asset->getOriginal('classroom_id');});} public function material(){return $this->belongsTo(InventoryMaterial::class,'material_id');} public function categoryRelation(){return $this->belongsTo(InventoryCategory::class,'category_id');} public function classroom(){return $this->belongsTo(\Modules\Classroom\Models\Classroom::class);} public function holdingUnit(){return $this->belongsTo(\Modules\Unit\Models\Unit::class,'holding_unit_id');} public function repairs(){return $this->hasMany(InventoryRepair::class,'asset_id');} public function proposals(){return $this->hasMany(InventoryProposalItem::class,'asset_id');} }
